import java.util.*;public class NestedIterator implements Iterator<Integer>{Deque<NestedInteger>st=new ArrayDeque<>();public NestedIterator(List<NestedInteger>a){for(int i=a.size()-1;i>=0;i--)st.push(a.get(i));}void prep(){while(!st.isEmpty()&&!st.peek().isInteger()){List<NestedInteger>v=st.pop().getList();for(int i=v.size()-1;i>=0;i--)st.push(v.get(i));}}public Integer next(){prep();return st.pop().getInteger();}public boolean hasNext(){prep();return!st.isEmpty();}}
